def bucket_histogram(values: Iterable[float], boundaries: Iterable[float],
                     *, cumulative: bool = False) -> list[int]:
    bounds = sorted(boundaries)
    counts = [0] * (len(bounds) + 1)
    for v in values:
        idx = bisect.bisect_left(bounds, v)
        counts[idx] += 1
